using System;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;public static class ProbeMaskMO{public static async Task<string> Main(){EditorApplication.ExecuteMenuItem("Window/General/Game");UnityEditorInternal.InternalEditorUtility.RepaintAllViews();await Awaitable.EndOfFrameAsync();var l=Object.FindFirstObjectByType<ElevatorLesson>();var p=GraphicsSettings.currentRenderPipeline as UniversalRenderPipelineAsset;var q=new SerializedObject(p);var rd=q.FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue as ScriptableRendererData;return Newtonsoft.Json.JsonConvert.SerializeObject(new{playing=Application.isPlaying,frame=Time.frameCount,last=ElevatorSilhouetteOutlineFeature.LastFrame,count=ElevatorSilhouetteOutlineFeature.LastTargetCount,active=ElevatorOutlineTarget.Active.Count,visible=ElevatorOutlineTarget.Active.Count(t=>t&&t.Visible),pipeline=AssetDatabase.GetAssetPath(p),renderer=AssetDatabase.GetAssetPath(rd),features=rd.rendererFeatures.Select(f=>new{name=f.name,type=f.GetType().Name,active=f.isActive}).ToArray(),camera=l.playerCamera.enabled,rect=l.playerCamera.rect.ToString(),target=l.playerCamera.targetTexture?l.playerCamera.targetTexture.name:null,errors=UnityEditor.EditorUtility.scriptCompilationFailed});}}